async function getMeta(args) {
  var parts = String((args && args.link) || '').split('|');
  if (parts.length !== 3 || parts[0] !== 'freetv') return {};
  var channels = DATA[parts[1]];
  if (!channels) return {};
  var ch = channels[parseInt(parts[2], 10)];
  if (!ch) return {};
  return {
    title: ch[0],
    image: ch[1],
    synopsis: 'Live TV' + (ch[2] ? ' \u00b7 ' + ch[2] : ''),
    type: 'tv',
    linkList: [
      {
        title: 'Live',
        directLinks: [
          { title: ch[0] + ' (Live)', link: ch[3], type: 'tv' }
        ]
      }
    ]
  };
}

// CommonJS exports for the unictoos sandbox (exact export names matter).
if (typeof module !== 'undefined' && module.exports) {
  module.exports.getMeta = getMeta;
}
